/*!
 * Mustafa Soft - animated services slider (single file, images embedded).
 * Add ONE line before </body> in index.html:  <script src="/slider.js" defer></script>
 * To change texts/search words, edit the SLIDES list below.
 */
(function () {
  'use strict';

  var SLIDES = [
    { img: 'data:image/webp;base64,', c: '#1f2937', title: 'إزالة حساب جوجل (FRP)',  sub: 'فك قفل حماية إعادة ضبط المصنع لأجهزة أندرويد', q: 'FRP' },
    { img: 'data:image/webp;base64,', c: '#111827', title: 'إزالة iCloud رسمي',       sub: 'فك قفل التنشيط لأجهزة آيفون وآيباد',            q: 'iCloud' },
    { img: 'data:image/webp;base64,', c: '#111827', title: 'إزالة MDM',               sub: 'إزالة إدارة الجهاز عن الأجهزة المقفلة',          q: 'MDM' },
    { img: 'data:image/webp;base64,', c: '#0f3b4d', title: 'إزالة حساب هونر',         sub: 'فك قفل حساب Honor للأجهزة المدعومة',            q: 'Honor' },
    { img: 'data:image/webp;base64,', c: '#1e3a8a', title: 'إزالة حساب شاومي',        sub: 'فك قفل Mi Account لأجهزة Xiaomi وRedmi وPOCO',   q: 'Xiaomi' },
    { img: 'data:image/webp;base64,', c: '#0b3d2e', title: 'تفعيل جميع الأدوات',      sub: 'تفعيل وتجديد أدوات الفك والصيانة الأكثر استخدامًا', q: 'Tool' }
  ];
  var BTN_TEXT = 'اطلب الآن';
  var NOTE = 'الخدمات مخصصة لأصحاب الأجهزة الأصليين فقط.';
  var INTERVAL = 5000; // ms between slides

  var reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;

  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text != null) e.textContent = text;
    return e;
  }

  function injectCss() {
    if (document.getElementById('ms-slider-css')) return;
    var s = document.createElement('style');
    s.id = 'ms-slider-css';
    s.textContent =
      '.ms-wrap{margin:0 0 22px}' +
      '.ms-slider{position:relative;overflow:hidden;border-radius:18px;background:#0f172a;aspect-ratio:4/3;max-height:560px;direction:rtl;touch-action:pan-y;-webkit-user-select:none;user-select:none;box-shadow:0 10px 28px rgba(15,23,42,.18)}' +
      '@media(min-width:720px){.ms-slider{aspect-ratio:2/1}}' +
      '.ms-slide{position:absolute;inset:0;opacity:0;visibility:hidden;transition:opacity .8s ease,visibility .8s}' +
      '.ms-slide.on{opacity:1;visibility:visible}' +
      '.ms-slide img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 30%;transform:scale(1)}' +
      '.ms-slide.on img{animation:msZoom 7s ease-out forwards}' +
      '@keyframes msZoom{from{transform:scale(1)}to{transform:scale(1.08)}}' +
      '.ms-slide:after{content:"";position:absolute;inset:0;background:linear-gradient(to top,rgba(2,6,23,.9) 0%,rgba(2,6,23,.6) 36%,rgba(2,6,23,0) 68%)}' +
      '.ms-cap{position:absolute;z-index:2;right:0;left:0;bottom:0;padding:16px 18px 40px;color:#fff;text-align:right}' +
      '.ms-cap h3,.ms-cap p,.ms-cap .ms-btn{opacity:0;transform:translateY(14px);transition:opacity .6s ease,transform .6s ease}' +
      '.ms-slide.on .ms-cap h3{opacity:1;transform:none;transition-delay:.25s}' +
      '.ms-slide.on .ms-cap p{opacity:.92;transform:none;transition-delay:.4s}' +
      '.ms-slide.on .ms-cap .ms-btn{opacity:1;transform:none;transition-delay:.55s}' +
      '.ms-cap h3{margin:0 0 4px;font-size:22px;line-height:1.35;text-shadow:0 2px 10px rgba(0,0,0,.45)}' +
      '.ms-cap p{margin:0 0 12px;font-size:14px;line-height:1.6}' +
      '.ms-btn{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 20px;border:0;border-radius:11px;background:#fff;color:#0f172a;font:inherit;font-weight:700;font-size:14px;cursor:pointer}' +
      '.ms-btn:focus-visible,.ms-nav:focus-visible,.ms-dot:focus-visible{outline:2px solid #60a5fa;outline-offset:2px}' +
      '.ms-nav{position:absolute;z-index:3;top:42%;width:38px;height:38px;border:0;border-radius:50%;background:rgba(15,23,42,.5);color:#fff;font-size:24px;line-height:1;cursor:pointer;display:none}' +
      '@media(min-width:720px){.ms-nav{display:block}}' +
      '.ms-prev{right:10px}.ms-next{left:10px}' +
      '.ms-dots{position:absolute;z-index:3;left:0;right:0;bottom:12px;display:flex;justify-content:center;gap:6px}' +
      '.ms-dot{width:8px;height:8px;padding:0;border:0;border-radius:99px;background:rgba(255,255,255,.5);cursor:pointer;transition:width .3s,background .3s}' +
      '.ms-dot.on{width:22px;background:#fff}' +
      '.ms-note{margin:8px 4px 0;font-size:12px;color:#64748b;text-align:center}' +
      '@media(prefers-reduced-motion:reduce){.ms-slide,.ms-cap h3,.ms-cap p,.ms-cap .ms-btn{transition:none}.ms-slide.on img{animation:none}}';
    document.head.appendChild(s);
  }

  function searchFor(q) {
    var input = document.getElementById('q');
    if (!input) return;
    input.value = q;
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.scrollIntoView({ behavior: reduce ? 'auto' : 'smooth', block: 'center' });
  }

  function build() {
    var wrap = el('div', 'ms-wrap');
    var slider = el('section', 'ms-slider');
    slider.setAttribute('role', 'region');
    slider.setAttribute('aria-roledescription', 'carousel');
    slider.setAttribute('aria-label', 'عروض الخدمات');

    var slides = [], dots = [], cur = 0, timer = null, resumeAt = 0;

    SLIDES.forEach(function (d, i) {
      var s = el('article', 'ms-slide');
      s.style.background = d.c;
      s.setAttribute('aria-label', (i + 1) + ' / ' + SLIDES.length);
      var img = new Image();
      img.alt = '';
      img.decoding = 'async';
      img.src = d.img;
      s.appendChild(img);
      var cap = el('div', 'ms-cap');
      cap.appendChild(el('h3', null, d.title));
      cap.appendChild(el('p', null, d.sub));
      var b = el('button', 'ms-btn', BTN_TEXT);
      b.type = 'button';
      b.addEventListener('click', function () { searchFor(d.q); });
      cap.appendChild(b);
      s.appendChild(cap);
      slider.appendChild(s);
      slides.push(s);
    });

    var prev = el('button', 'ms-nav ms-prev', '›');
    prev.type = 'button'; prev.setAttribute('aria-label', 'السابق');
    var next = el('button', 'ms-nav ms-next', '‹');
    next.type = 'button'; next.setAttribute('aria-label', 'التالي');
    slider.appendChild(prev);
    slider.appendChild(next);

    var dotBox = el('div', 'ms-dots');
    SLIDES.forEach(function (d, i) {
      var dot = el('button', 'ms-dot');
      dot.type = 'button';
      dot.setAttribute('aria-label', 'الشريحة ' + (i + 1));
      dot.addEventListener('click', function () { show(i, true); });
      dotBox.appendChild(dot);
      dots.push(dot);
    });
    slider.appendChild(dotBox);

    function show(i, manual) {
      cur = (i + slides.length) % slides.length;
      slides.forEach(function (s, k) {
        var on = k === cur;
        s.classList.toggle('on', on);
        s.setAttribute('aria-hidden', on ? 'false' : 'true');
        dots[k].classList.toggle('on', on);
        if (on) dots[k].setAttribute('aria-current', 'true'); else dots[k].removeAttribute('aria-current');
      });
      if (manual) resumeAt = Date.now() + 8000; // give the reader time after a manual change
    }

    function tick() {
      if (document.hidden || Date.now() < resumeAt) return;
      show(cur + 1, false);
    }
    function start() { if (!timer && !reduce) timer = setInterval(tick, INTERVAL); }
    function stop() { if (timer) { clearInterval(timer); timer = null; } }

    prev.addEventListener('click', function () { show(cur - 1, true); });
    next.addEventListener('click', function () { show(cur + 1, true); });

    // swipe (touch / mouse)
    var x0 = null;
    slider.addEventListener('pointerdown', function (e) { x0 = e.clientX; });
    slider.addEventListener('pointerup', function (e) {
      if (x0 == null) return;
      var dx = e.clientX - x0; x0 = null;
      if (Math.abs(dx) > 40) show(dx < 0 ? cur + 1 : cur - 1, true);
    });
    slider.addEventListener('pointercancel', function () { x0 = null; });
    slider.addEventListener('mouseenter', stop);
    slider.addEventListener('mouseleave', start);

    // run only while visible on screen
    if ('IntersectionObserver' in window) {
      new IntersectionObserver(function (entries) {
        entries[0].isIntersecting ? start() : stop();
      }, { threshold: 0.25 }).observe(slider);
    } else { start(); }

    show(0, false);
    wrap.appendChild(slider);
    wrap.appendChild(el('p', 'ms-note', NOTE));
    return wrap;
  }

  function init() {
    if (document.querySelector('.ms-wrap')) return;
    injectCss();
    var wrap = build();
    var pay = document.querySelector('.pay');
    var host = pay ? pay.parentNode : (document.querySelector('main') || document.body);
    host.insertBefore(wrap, pay || host.firstChild);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
